  job_id: jobId,
  job_type: j.job_type != null ? j.job_type : null,
  intervention_id: interventionId,
  tenant_id: payload.tenant_id != null ? payload.tenant_id : null,
  correlation_id: j.correlation_id != null ? j.correlation_id : (payload.correlation_id != null ? payload.correlation_id : null),
