const recoveryType = String(c.recovery_type || c.opportunity_type || "").toUpperCase();
const idleWindowElapsed = ["PAYMENT_FAILURE","PAYMENT_DECLINED"].includes(recoveryType)
  ? delayIsValid
  : delayIsValid && Number.isFinite(checkoutUpdatedMs) && (nowMs - checkoutUpdatedMs) >= configuredDelay * 60 * 1000;
const checks = {
