const destination_url = c.checkout_url || c.destination_url || null;
checks.destination_url = !!destination_url;
const failed = Object.keys(checks).filter(function (k) { return !checks[k]; });
const sendable = failed.length === 0;
const stepNumber = Math.max(1, Math.min(3, Number(c.step_number || 1)));
const previousMessages = Array.isArray(c.previous_messages)
  ? c.previous_messages.slice(0, 2).map((m) => ({
      step_number: Number(m.step_number || 0),
