const stepGuidance = stepNumber === 1
  ? "STEP 1 — RECONNECT: Open with a natural, warm human greeting. Acknowledge that life gets busy without claiming to know what the customer did. Make the next step feel effortless. Lead with a supplied product detail only if it genuinely helps. Offer a simple reply if they have a question."
  : stepNumber === 2
    ? "STEP 2 — REMOVE FRICTION: This is a genuinely new angle, not a louder reminder. Help with a likely decision question only when supported by supplied facts; otherwise invite the customer to ask about anything holding them back. Do not repeat the previous subject, opening, or sales angle."
