const resp = $json || {};
const pf = $("Preflight & AI Context").item.json;
const ng = $("Normalize & Guard").item.json;
const cfg = $("Init Worker").first().json;
const ctx = pf.ai_context || {};
const tok = $("Create Tracking Token").item.json || {};
const unsub = $("Create Unsubscribe Token").item.json || {};
const allowedUrl = ctx.destination_url;
let ai = null;
try {
  const content = resp.body && resp.body.choices && resp.body.choices[0] && resp.body.choices[0].message && resp.body.choices[0].message.content;
  ai = typeof content === "string" ? JSON.parse(content) : content;
} catch (e) { ai = null; }
function urlsIn(s) { return (String(s || "").match(/https?:\/\/[^\s"\)<]+/g)) || []; }
const flags = [];
let valid = !!ai && !!tok.token && !!tok.tracking_token_id && !!allowedUrl && !!unsub.token && !!unsub.unsubscribe_token_id;
if (!tok.token || !tok.tracking_token_id) flags.push("missing_tracking_token");
if (!allowedUrl) flags.push("missing_destination_url");
if (!unsub.token || !unsub.unsubscribe_token_id) flags.push("missing_unsubscribe_token");
if (valid) {
  if (!ai.subject || typeof ai.subject !== "string") { valid = false; flags.push("missing_subject"); }
  if (!ai.body || typeof ai.body !== "string" || ai.body.trim() === "") { valid = false; flags.push("missing_body"); }
  if ((ai.subject || "").length > 200 || (ai.body || "").length > 5000) { valid = false; flags.push("oversized"); }
  const urls = urlsIn(ai.body).concat(urlsIn(ai.opening)).concat(urlsIn(ai.cta_text)).concat(urlsIn(ai.subject));
  if (urls.length > 0) { valid = false; flags.push("grok_emitted_url"); }
}
const trustedUrl = tok.token ? ("https://ocyplckdojdubyrsxcxa.supabase.co/functions/v1/henvalt-public-mail-actions/track/" + encodeURIComponent(String(tok.token))) : "";
const unsubscribeUrl = unsub.token ? ("https://ocyplckdojdubyrsxcxa.supabase.co/functions/v1/henvalt-public-mail-actions/unsubscribe/" + encodeURIComponent(String(unsub.token))) : "";
let subject = null, bodyHtml = null, bodyText = null, cta = null;
const storeName = String(ctx.store_name || "Our store").trim().slice(0,100);
const branding = ctx.email_branding && typeof ctx.email_branding === "object" ? ctx.email_branding : {};
const isHexColor = (value) => typeof value === "string" && /^#[0-9a-fA-F]{6}$/.test(value);
const primaryColor = isHexColor(branding.primary_color) ? branding.primary_color : "#171717";
const pageColor = isHexColor(branding.background_color) ? branding.background_color : "#f4f4f1";
const accentColor = isHexColor(branding.accent_color) ? branding.accent_color : "#77776f";
const candidateLogo = typeof branding.logo_url === "string" ? branding.logo_url.trim() : "";
const logoUrl = /^https:\/\//i.test(candidateLogo) ? candidateLogo : "";
if (valid) {
  subject = ai.subject;
  cta = (ai.cta_text && String(ai.cta_text).trim()) ? String(ai.cta_text).trim().slice(0,60) : (String(ctx.recovery_type || "").toUpperCase() === "BROWSE_ABANDONMENT" ? "View product" : (String(ctx.recovery_type || "").toUpperCase() === "ABANDONED_CART" ? "Return to your cart" : "Return to your checkout"));
  const opening = ai.opening ? String(ai.opening) : "";
  const bodyMsg = String(ai.body);
  const escapeHtml = (s) => String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  const paragraphHtml = [opening, bodyMsg].filter(Boolean).map(s => "<p style=\"margin:0 0 16px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.65;color:#292929;\">" + escapeHtml(s).replace(/\n/g,"<br>") + "</p>").join("");
  const safeStore = escapeHtml(storeName);
  const safeCta = escapeHtml(cta);
  const headerBrand = logoUrl
    ? `<img src="${escapeHtml(logoUrl)}" alt="${safeStore}" width="160" style="display:block;max-width:160px;max-height:48px;width:auto;height:auto;object-fit:contain;border:0;">`
    : `<div style="font-family:Arial,Helvetica,sans-serif;font-size:20px;font-weight:700;letter-spacing:-.4px;color:${primaryColor};">${safeStore}</div>`;
  bodyHtml = `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="x-apple-disable-message-reformatting"><title>${escapeHtml(subject)}</title></head>
<body style="margin:0;padding:0;background:${pageColor};">
<div style="display:none;font-size:1px;color:${pageColor};line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;">Your ${String(ctx.recovery_type || "").toUpperCase() === "BROWSE_ABANDONMENT" ? "product page is here whenever you are." : (String(ctx.recovery_type || "").toUpperCase() === "ABANDONED_CART" ? "cart is ready whenever you are." : "checkout is ready whenever you are.")}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${pageColor};width:100%;">
<tr><td align="center" style="padding:34px 14px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #e9e9e5;border-radius:16px;overflow:hidden;">
<tr><td style="padding:27px 34px 23px;border-bottom:1px solid #eeeeea;">${headerBrand}<div style="margin-top:7px;font-family:Arial,Helvetica,sans-serif;font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#8a8a83;">A little note for you</div></td></tr>
