<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:26px 0 10px;"><tr><td bgcolor="${primaryColor}" style="border-radius:8px;"><a href="${escapeHtml(trustedUrl)}" style="display:inline-block;padding:15px 25px;font-family:Arial,Helvetica,sans-serif;font-size:14px;font-weight:700;color:#ffffff;text-decoration:none;border-radius:8px;background:${primaryColor};">${safeCta}</a></td></tr></table>
<p style="margin:12px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.5;color:#8a8a83;">${String(ctx.recovery_type || "").toUpperCase() === "BROWSE_ABANDONMENT" ? "This link takes you back to the product you viewed." : (String(ctx.recovery_type || "").toUpperCase() === "ABANDONED_CART" ? "Your cart link takes you back to the items you selected." : "Your checkout link will take you back to where you left off.")}</p></td></tr>
