</td></tr></table></body></html>`;
  bodyText = [storeName, "", opening, bodyMsg, "", cta + ": " + trustedUrl, "", "If you have a question, simply reply to this email.", "Unsubscribe: " + unsubscribeUrl, "", ""].filter(Boolean).join("\n");
