  reply_to: pf.reply_to || null,
  delivery_mode: pf.delivery_mode,
  template_reference: pf.template_reference,
  tenant_id: pf.tenant_id,
  intervention_id: pf.intervention_id,
  recovery_id: pf.recovery_id,
  opportunity_id: pf.opportunity_id,
  recovery_type: ctx.recovery_type || null,
  store_name: storeName,
  correlation_id: pf.correlation_id,
  job_id: pf.job_id,
  worker_id: pf.worker_id,
  attempts: ng.attempts,
  ai_provider: "GROQ",
  ai_model: pf.model,
  prompt_version: cfg.prompt_version,
  policy_version: cfg.policy_version,
